Addressed visible stage operands and labels: h=ReLU(T+S−.5) | binary T/S · supplied toy neuron. Controls: T only, S only, Both, Reset. Changed computed rows: T=1; S=0; preactivation=0.5 / h=max(0,preactivation)=0.5 / same h: (1,0) / (0,1) / activation≠unique feature | T=0; S=1; preactivation=0.5 / h=max(0,preactivation)=0.5 / same h: (1,0) / (0,1) / activation≠unique feature | T=1; S=1; preactivation=1.5 / h=max(0,preactivation)=1.5 / same h: (1,1) / activation≠unique feature. Retained computed witnesses: 1/0→h0.5; inputs=2 | 0/1→h0.5; inputs=2 | 1/1→h1.5; inputs=1. Numeric display is rounded to three decimals unless explicitly shown otherwise; source computations retain full precision. Exact expressions: // Bounded owner construction; no external model / shared runtime engine.
export const sum=(a:number[])=>a.reduce((s,x)=>s+x,0);
export const dot=(a:number[],b:number[])=>sum(a.map((x,i)=>x*b[i]));
export const f=(x:number)=>Number.isFinite(x)?String(Number(x.toFixed(3))):'∞';
export function compute(mode:number){
const [T,S]=[[1,0],[0,1],[1,1]][mode],h=Math.max(0,T+S-.5),inputs=[[0,0],[1,0],[0,1],[1,1]],same=inputs.filter(([a,b])=>Math.max(0,a+b-.5)===h);return{values:[h,same.length],rows:[`T=${T}; S=${S}; preactivation=${f(T+S-.5)}`,`h=max(0,preactivation)=${f(h)}`,`same h: ${same.map(x=>`(${x.join(',')})`).join(' / ')}`,`activation≠unique feature`],receipt:`${T}/${S}→h${f(h)}; inputs=${same.length}`};
}
